values
  ('b22da4b3-9bf2-53fd-bee4-014572442f54', '22222222-2222-2222-2222-222222222217', 'short', '有公共端点的两条射线组成的图形叫做角，这个公共端点叫做角的顶点， 这两条射线叫做角的边.当角的两边在一条直线上时，组成的角叫做平角 （180°）.', null, '', '', '数学/第7章 平面几何（1）含解析的合订版（适合使用在线文档查看的同学）.pdf', 3, true, 97, null),
  ('8f7d7d47-8c54-597f-a480-07e83663330f', '22222222-2222-2222-2222-222222222217', 'short', '平角的一半叫做直角（90° ）；小于直角的角叫做锐角；大于直角且小于 平角的角叫做钝角.', null, '', '', '数学/第7章 平面几何（1）含解析的合订版（适合使用在线文档查看的同学）.pdf', 3, true, 98, null),
  ('f208fde9-49b1-5d01-9d87-3d9db968ee29', '22222222-2222-2222-2222-222222222217', 'short', '如果两个角的和是一个直角，那么这两个角互为余角，其中一个角叫做 另一个角的余角.', null, '', '', '数学/第7章 平面几何（1）含解析的合订版（适合使用在线文档查看的同学）.pdf', 3, true, 99, null),
  ('396fbe17-b475-5647-82ce-889c6bdb16d6', '22222222-2222-2222-2222-222222222217', 'short', '如果两个角的和是一个平角，那么这两个角互为补角，其中一个角叫做 另一个角的补角. 二、角的平分线及其性质', null, '', '', '数学/第7章 平面几何（1）含解析的合订版（适合使用在线文档查看的同学）.pdf', 3, true, 100, null),
  ('dc765cde-be65-566e-a285-4e3ff486d061', '22222222-2222-2222-2222-222222222217', 'short', '一条射线把一个角分成两个相等的角，这条射线叫做这个角的平分线. 你的坚持，终将美好！ 2', null, '', '', '数学/第7章 平面几何（1）含解析的合订版（适合使用在线文档查看的同学）.pdf', 3, true, 101, null),
  ('00eee7b4-1393-59d7-9e09-349567f84e88', '22222222-2222-2222-2222-222222222217', 'short', '角平分线上的点到这个角的两边的距离相等. 到一个角的两边距离相等 的点在这个角的平分线上. 三、平行线', null, '', '', '数学/第7章 平面几何（1）含解析的合订版（适合使用在线文档查看的同学）.pdf', 4, true, 102, null),
  ('f78b503e-044f-5894-9d0f-47329092463d', '22222222-2222-2222-2222-222222222217', 'short', '在同一个平面内，不相交的两条直线叫做平行线.平行用符号“∥”表 示，如“𝐴𝐵∥𝐶𝐷”，读作“𝐴𝐵平行于𝐶𝐷”.', null, '', '', '数学/第7章 平面几何（1）含解析的合订版（适合使用在线文档查看的同学）.pdf', 4, true, 103, null),
  ('a382c367-e8e8-53a3-8416-55793e6f227f', '22222222-2222-2222-2222-222222222217', 'short', '对顶角：∠1与∠2是对顶角，对顶角相等.', null, '', '', '数学/第7章 平面几何（1）含解析的合订版（适合使用在线文档查看的同学）.pdf', 4, true, 104, null),
  ('ef585eb4-aafc-58f8-a7fa-58c99c498e20', '22222222-2222-2222-2222-222222222217', 'short', '同位角：∠1与∠4是同位角，两直线平行，同位角相等.', null, '', '', '数学/第7章 平面几何（1）含解析的合订版（适合使用在线文档查看的同学）.pdf', 4, true, 105, null),
  ('74c322fc-1853-5872-823b-79c675987e72', '22222222-2222-2222-2222-222222222217', 'short', '内错角：∠2与∠4是内错角，两直线平行，内错角相等.', null, '', '', '数学/第7章 平面几何（1）含解析的合订版（适合使用在线文档查看的同学）.pdf', 4, true, 106, null),
  ('5de103e0-96e9-50a2-b6cf-770125559565', '22222222-2222-2222-2222-222222222217', 'short', '同旁内角：∠3与∠4是同旁内角，两直线平行，同旁内角互补. 四、其他知识', null, '', '', '数学/第7章 平面几何（1）含解析的合订版（适合使用在线文档查看的同学）.pdf', 4, true, 107, null),
  ('5592140e-a087-5f2a-aebc-3671bf244c6b', '22222222-2222-2222-2222-222222222217', 'short', '垂线：当两条直线相交所成的四个角中，有一个角是直角时，即两条直 线互相垂直，其中一条直线叫作另一条直线的垂线，交点叫垂足.', null, '', '', '数学/第7章 平面几何（1）含解析的合订版（适合使用在线文档查看的同学）.pdf', 4, true, 108, null),
  ('fe0c750e-11db-5a6a-8aea-a733f84867b8', '22222222-2222-2222-2222-222222222217', 'short', '垂直平分线：又称 “中垂线”，是指经过某一条线段的中点，并且垂直于 这条线段的直线.垂直平分线可以看成到线段两个端点距离相等的点的 集合，垂直平分线是线段的一条对称轴.', null, '', '', '数学/第7章 平面几何（1）含解析的合订版（适合使用在线文档查看的同学）.pdf', 4, true, 109, null),
  ('3ef6b61c-ee82-5fe3-8285-7c25b239bb50', '22222222-2222-2222-2222-222222222217', 'short', '中位线：平面几何内连接三角形任意两边中点的线段或连接梯形两腰中 点的线段. 你的坚持，终将美好！ 3', null, '', '', '数学/第7章 平面几何（1）含解析的合订版（适合使用在线文档查看的同学）.pdf', 4, true, 110, null),
  ('2666c972-3c9d-52be-8ddd-89abd797219a', '22222222-2222-2222-2222-222222222217', 'short', '三角形全等：经过翻转、平移、旋转后，能够完全重合的两个三角形叫 作全等三角形. 它们的三条边和三个角都对应相等.', null, '', '', '数学/第7章 平面几何（1）含解析的合订版（适合使用在线文档查看的同学）.pdf', 5, true, 111, null),
  ('41c111a9-3ebe-50b3-924c-29b401e172e7', '22222222-2222-2222-2222-222222222217', 'short', '三角形相似：三个角分别相等，三条边对应成比例的两个三角形叫作相 似三角形.', null, '', '', '数学/第7章 平面几何（1）含解析的合订版（适合使用在线文档查看的同学）.pdf', 5, true, 112, null),
  ('e1021e20-a5b6-50a4-9fe3-078ff43481d9', '22222222-2222-2222-2222-222222222217', 'short', '三角形的稳定性：三角形的三边如果确定后，它的形状、大小就确定了.', null, '', '', '数学/第7章 平面几何（1）含解析的合订版（适合使用在线文档查看的同学）.pdf', 5, true, 113, null),
  ('09977661-ea1c-5ce0-903a-32eaae322d6d', '22222222-2222-2222-2222-222222222217', 'short', '平行四边形：两组对边分别平行的四边形叫作平行四边形.', null, '', '', '数学/第7章 平面几何（1）含解析的合订版（适合使用在线文档查看的同学）.pdf', 5, true, 114, null),
  ('79c3eee2-d742-57cf-aa91-ec7174100dbc', '22222222-2222-2222-2222-222222222217', 'short', '矩形：有一个角是直角的平行四边形叫作矩形（通常也叫作长方形）.', null, '', '', '数学/第7章 平面几何（1）含解析的合订版（适合使用在线文档查看的同学）.pdf', 5, true, 115, null),
  ('e444aed4-74ae-5baf-a7a5-b6a0c7a74d8d', '22222222-2222-2222-2222-222222222217', 'short', '菱形：有一组邻边相等的平行四边形叫作菱形.', null, '', '', '数学/第7章 平面几何（1）含解析的合订版（适合使用在线文档查看的同学）.pdf', 5, true, 116, null),
  ('e4cf76cb-f410-56a1-b2d7-3857b3947dc7', '22222222-2222-2222-2222-222222222217', 'short', '正方形：有一组邻边相等且有一个角是直角的平行四边形叫作正方形.', null, '', '', '数学/第7章 平面几何（1）含解析的合订版（适合使用在线文档查看的同学）.pdf', 5, true, 117, null),
  ('ed23bd9a-d4e2-5681-b3c4-96087f731e63', '22222222-2222-2222-2222-222222222217', 'short', '梯形：只有一组对边平行的四边形叫作梯形.', null, '', '', '数学/第7章 平面几何（1）含解析的合订版（适合使用在线文档查看的同学）.pdf', 5, true, 118, null),
  ('c9023e82-f7e5-50dc-a224-967ea355902a', '22222222-2222-2222-2222-222222222217', 'short', '角的弧度制：把圆弧长度和半径的比值称为对应圆周角的弧度.', null, '', '', '数学/第7章 平面几何（1）含解析的合订版（适合使用在线文档查看的同学）.pdf', 5, true, 119, null),
  ('95a2ae31-5e22-59da-a0d5-412042940037', '22222222-2222-2222-2222-222222222217', 'short', '1 弧度= 180° π ，1°= π 180 弧度.（π弧度=180°）', null, '', '', '数学/第7章 平面几何（1）含解析的合订版（适合使用在线文档查看的同学）.pdf', 5, true, 120, null),
  ('92c8d89e-173f-5709-977f-60d0dc5614d8', '22222222-2222-2222-2222-222222222217', 'short', '几个常用的角：360° = 2π，90° = π 2，60° = π 3，45° = π 4，30° = π 6.', null, '', '', '数学/第7章 平面几何（1）含解析的合订版（适合使用在线文档查看的同学）.pdf', 5, true, 121, null),
  ('b1eebc2f-89f5-5421-96fd-cbda45f08b32', '22222222-2222-2222-2222-222222222217', 'short', '圆：在同一平面内，到定点的距离等于定长的点的集合叫作圆，这个定 点叫圆心，定长是圆半径的长度.', null, '', '', '数学/第7章 平面几何（1）含解析的合订版（适合使用在线文档查看的同学）.pdf', 5, true, 122, null),
  ('e9e42e50-2bc4-53d1-9bca-000370731503', '22222222-2222-2222-2222-222222222217', 'short', '圆心角：顶点在圆心上的角叫作圆心角,圆心角度数等于所对的弧的度数.', null, '', '', '数学/第7章 平面几何（1）含解析的合订版（适合使用在线文档查看的同学）.pdf', 5, true, 123, null),
  ('0ec70f2d-126d-5f72-a4ac-15a2b807e0b9', '22222222-2222-2222-2222-222222222217', 'short', '圆周角：顶点在圆上,且它的两边分别与圆有另一个交点的角叫作圆周角.', null, '', '', '数学/第7章 平面几何（1）含解析的合订版（适合使用在线文档查看的同学）.pdf', 5, true, 124, null),
  ('4e0513ff-3ccf-5da4-8a3f-154a6ea88acc', '22222222-2222-2222-2222-222222222217', 'short', '弦切角：顶点在圆上，一边和圆相交，另一边和圆相切的角叫作弦切角. 弦切角的度数等于它所夹的弧对应的圆心角度数的一半，等于它所夹的 弧对应的圆周角度数.', null, '', '', '数学/第7章 平面几何（1）含解析的合订版（适合使用在线文档查看的同学）.pdf', 5, true, 125, null),
  ('0c356ffa-6433-535c-a4c7-96e2de88fb8a', '22222222-2222-2222-2222-222222222217', 'short', '扇形：一条圆弧和经过这条圆弧两端的两条半径所围成的图形叫作扇形.', null, '', '', '数学/第7章 平面几何（1）含解析的合订版（适合使用在线文档查看的同学）.pdf', 5, true, 126, null),
  ('fcb4e6a4-ecc4-5689-a447-b34675d8e683', '22222222-2222-2222-2222-222222222217', 'short', '弓形：由弦及其所对的弧组成的图形叫作弓形. 你的坚持，终将美好！ 4 考点1：三角形 一、三角形定义 由不在同一直线的三条线段首尾依次连接所组成的图形叫做三角形，三角 形有三条边、三个内角和三个顶点，三角形可以用符号△表示，顶点是 𝐴, 𝐵, 𝐶的三角形，记作△𝐴𝐵𝐶，读作“三角形𝐴𝐵𝐶”.△𝐴𝐵𝐶的三边可用𝑎, 𝑏, 𝑐 表示，顶点𝐴 所对应的边𝐵𝐶 用𝑎 来表示，顶点𝐵 所对应的边𝐴𝐶 用𝑏 来表示， 顶点𝐶所对应的边𝐴𝐵用𝑐来表示. 二、三角形性质', null, '', '', '数学/第7章 平面几何（1）含解析的合订版（适合使用在线文档查看的同学）.pdf', 5, true, 127, null),
  ('369894e9-5384-550c-ae17-754cf0bf5983', '22222222-2222-2222-2222-222222222217', 'short', '中线：连结一个顶点和它对边中点的线段（𝐴𝐷）.', null, '', '', '数学/第7章 平面几何（1）含解析的合订版（适合使用在线文档查看的同学）.pdf', 6, true, 128, null),
  ('2e3a26ea-bd91-5f66-97cd-957bce67448f', '22222222-2222-2222-2222-222222222217', 'short', '中位线：三角形两边中点的连线平行于第三边且等于第三边长度的一半.', null, '', '', '数学/第7章 平面几何（1）含解析的合订版（适合使用在线文档查看的同学）.pdf', 6, true, 129, null),
  ('55ff6362-1a9e-5e21-9afe-99eabf603e95', '22222222-2222-2222-2222-222222222217', 'short', '重心：三角形三条中线的交点.', null, '', '', '数学/第7章 平面几何（1）含解析的合订版（适合使用在线文档查看的同学）.pdf', 6, true, 130, null),
  ('5e387926-79ba-5b3f-815b-ce1a88a8bfac', '22222222-2222-2222-2222-222222222217', 'short', '重心分中线上下两部分之比为2:1.', null, '', '', '数学/第7章 平面几何（1）含解析的合订版（适合使用在线文档查看的同学）.pdf', 6, true, 131, null),
  ('0c6c3dca-bb37-5b60-93d3-1d2292af2fc6', '22222222-2222-2222-2222-222222222217', 'short', '重心平分三角形面积，即𝑆△𝐴𝐵𝑂= 𝑆△𝐵𝐶𝑂= 𝑆△𝐴𝐶𝑂= 1 3 𝑆△𝐴𝐵𝐶. 你的坚持，终将美好！ 5 三、三角形的内角与外角', null, '', '', '数学/第7章 平面几何（1）含解析的合订版（适合使用在线文档查看的同学）.pdf', 6, true, 132, null),
  ('700a1b07-b77f-5ba0-b034-af3cc44d7ae6', '22222222-2222-2222-2222-222222222217', 'short', '内角：三角形内角和为180°. ∠1+∠2+∠3=180°.', null, '', '', '数学/第7章 平面几何（1）含解析的合订版（适合使用在线文档查看的同学）.pdf', 7, true, 133, null),
  ('b6ceb84c-e8fe-54df-ae58-c0916eba737c', '22222222-2222-2222-2222-222222222217', 'short', '外角：三角形一个外角等于与之不相邻的两个内角之和. ∠4 = ∠1+∠2. 【注】在同一个三角形中：大角对大边，小角对小边，等角对等边. 题型1：考查角度的求解', null, '', '', '数学/第7章 平面几何（1）含解析的合订版（适合使用在线文档查看的同学）.pdf', 7, true, 134, null),
  ('18d35718-ac0d-582a-90b4-fc751891f7a3', '22222222-2222-2222-2222-222222222217', 'mcq', '知知△𝐴𝐵𝐶 中，∠𝐶= 31° ，∠𝐴𝐵𝐶 的角平分线𝐵𝐷 交𝐴𝐶 于𝐷 ，如果𝐷𝐸 垂 直平分𝐵𝐶，那么∠𝐴= ( ).', '[{"key": "A", "text": "55°"}, {"key": "B", "text": "67°"}, {"key": "C", "text": "77°"}, {"key": "D", "text": "87°"}, {"key": "E", "text": "92°"}]'::jsonb, '', '', '数学/第7章 平面几何（1）含解析的合订版（适合使用在线文档查看的同学）.pdf', 7, true, 135, null),
  ('fdf56773-3069-554f-bcfc-403f7768a52f', '22222222-2222-2222-2222-222222222217', 'mcq', '若𝐴𝐵//𝐶𝐸，𝐶𝐸= 𝐷𝐸，且∠𝐶𝐸𝐷= 45°，则∠𝐵= ( ).', '[{"key": "A", "text": "45°"}, {"key": "B", "text": "60°"}, {"key": "C", "text": "67.5°"}, {"key": "D", "text": "112.5°"}, {"key": "E", "text": "135°"}]'::jsonb, '', '', '数学/第7章 平面几何（1）含解析的合订版（适合使用在线文档查看的同学）.pdf', 8, true, 136, null),
  ('afc58de1-f459-50b5-9e1d-1730addd7302', '22222222-2222-2222-2222-222222222217', 'short', '构成三角形的等价条件（三条边为𝑎, 𝑏, 𝑐）', null, '', '', '数学/第7章 平面几何（1）含解析的合订版（适合使用在线文档查看的同学）.pdf', 9, true, 137, null),
  ('97a4efde-7892-5f5d-948d-4ac6a424bf86', '22222222-2222-2222-2222-222222222217', 'short', '任意两边之和大于第三边，即 { 𝑎+ 𝑏> 𝑐, 𝑎+ 𝑐> 𝑏, 𝑐+ 𝑏> 𝑎. （☆☆）', null, '', '', '数学/第7章 平面几何（1）含解析的合订版（适合使用在线文档查看的同学）.pdf', 9, true, 138, null),
  ('44014153-b3e1-56e9-a230-2ec3bafa8085', '22222222-2222-2222-2222-222222222217', 'short', '任意两边之差小于第三边，即 { 𝑎> 𝑐−𝑏, 𝑏> 𝑐−𝑎 𝑎> 𝑏−𝑐, 𝑐> 𝑏−𝑎 𝑐> 𝑎−𝑏, 𝑏> 𝑎−𝑐 ⇒{ |𝑏−𝑐| < 𝑎, |𝑎−𝑐| < 𝑏, |𝑎−𝑏| < 𝑐. 【注】判断三条线段能否组成三角形时，我们只需要判断，较小的两边 相加大于最大边即可. 题型2：考查三角形的三边关系', null, '', '', '数学/第7章 平面几何（1）含解析的合订版（适合使用在线文档查看的同学）.pdf', 9, true, 139, null),
  ('185b4f11-a79d-50c3-855b-d92a8e07a7bf', '22222222-2222-2222-2222-222222222217', 'mcq', '知知三角形两边的边长分别是4 和10，则此三角形三边的边长可能 是( ).', '[{"key": "A", "text": "4"}, {"key": "B", "text": "5"}, {"key": "C", "text": "6"}, {"key": "D", "text": "11"}, {"key": "E", "text": "16"}]'::jsonb, '', '', '数学/第7章 平面几何（1）含解析的合订版（适合使用在线文档查看的同学）.pdf', 9, true, 140, null),
  ('fbdca709-e3e2-5c95-bc19-61ceda851901', '22222222-2222-2222-2222-222222222217', 'short', '三条长度分别为𝑎, 𝑏, 𝑐的线段能构成一个三角形.', null, '', '', '数学/第7章 平面几何（1）含解析的合订版（适合使用在线文档查看的同学）.pdf', 9, true, 141, null),
  ('c8c7ce62-9c8e-5194-aa06-a2eff5174d10', '22222222-2222-2222-2222-222222222217', 'short', '𝑎+ 𝑏> 𝑐.', null, '', '', '数学/第7章 平面几何（1）含解析的合订版（适合使用在线文档查看的同学）.pdf', 9, true, 142, null),
  ('b402d33b-a807-566d-8805-d21c8ce4c253', '22222222-2222-2222-2222-222222222217', 'short', '𝑏−𝑐< 𝑎. 你的坚持，终将美好！ 8 你的坚持，终将美好！ 9 五、特殊三角形', null, '', '', '数学/第7章 平面几何（1）含解析的合订版（适合使用在线文档查看的同学）.pdf', 9, true, 143, null),
  ('6de6261a-26ce-5092-bfc0-2578776b2a9e', '22222222-2222-2222-2222-222222222217', 'short', '直角三角形', null, '', '', '数学/第7章 平面几何（1）含解析的合订版（适合使用在线文档查看的同学）.pdf', 11, true, 144, null),
  ('b513f833-39d0-56e4-af47-189afa82c9df', '22222222-2222-2222-2222-222222222217', 'short', '两条直角边的平方和等于斜边的平方（勾股定理）. 例如：直角三角形两直角边为𝑎, 𝑏，斜边为𝑐，则有𝑎2 + 𝑏2 = 𝑐2， 常见勾股数：（3,4,5），（6,8,10），（9,12,15）； （5,12,13）；（7,24,25）.', null, '', '', '数学/第7章 平面几何（1）含解析的合订版（适合使用在线文档查看的同学）.pdf', 11, true, 145, null),
  ('b0c493d2-33c4-57a9-be92-80af98012550', '22222222-2222-2222-2222-222222222217', 'short', '直角三角形斜边上的中线等于斜边的一半.', null, '', '', '数学/第7章 平面几何（1）含解析的合订版（适合使用在线文档查看的同学）.pdf', 11, true, 146, null),
  ('ba572a01-c8ef-5c17-b62d-d559214a456b', '22222222-2222-2222-2222-222222222217', 'short', '直角三角形30°角所对的边等于斜边的一半，且三边之比为1: 2: √3.', null, '', '', '数学/第7章 平面几何（1）含解析的合订版（适合使用在线文档查看的同学）.pdf', 11, true, 147, null),
  ('8681f2fc-ea8c-586b-badc-244387ffc3b8', '22222222-2222-2222-2222-222222222217', 'short', '两直角边的乘积等于斜边与其高线的乘积. 即𝐴𝐵∙𝐵𝐶= 𝐴𝐶∙𝐵𝐷，（面积恒定）. 你的坚持，终将美好！ 10', null, '', '', '数学/第7章 平面几何（1）含解析的合订版（适合使用在线文档查看的同学）.pdf', 11, true, 148, null),
  ('e8bc9d66-63d9-5ee8-a8b0-28904fa56a96', '22222222-2222-2222-2222-222222222217', 'short', '在直角三角形中，斜边上的高线是两直角边在斜边上的投影的比例中 项，每条直角边是它们在斜边上的投影和斜边的比例中项 （射影定理）. { 𝐶𝐷2 = 𝐴𝐷⋅𝐵𝐷 𝐴𝐶2 = 𝐴𝐷⋅𝐴𝐵 𝐵𝐶2 = 𝐵𝐷⋅𝐴𝐵', null, '', '', '数学/第7章 平面几何（1）含解析的合订版（适合使用在线文档查看的同学）.pdf', 12, true, 149, null),
  ('d8675b9e-7408-5556-9890-2a69849f5c53', '22222222-2222-2222-2222-222222222217', 'short', '等腰直角三角形 （两个底角为45°）', null, '', '', '数学/第7章 平面几何（1）含解析的合订版（适合使用在线文档查看的同学）.pdf', 12, true, 150, null),
  ('ce9d3668-fdfc-56d7-85da-65782175b8df', '22222222-2222-2222-2222-222222222217', 'short', '三边之比为1: 1: √2.', null, '', '', '数学/第7章 平面几何（1）含解析的合订版（适合使用在线文档查看的同学）.pdf', 12, true, 151, null),
  ('ee6c725c-6671-517f-ae6c-077a5b68ebf6', '22222222-2222-2222-2222-222222222217', 'short', '面积公式：𝑆= 1 2 𝐴𝐵⋅𝐵𝐶= 1 2 𝑎2. 你的坚持，终将美好！ 11 题型3：考查直角三角形的应用', null, '', '', '数学/第7章 平面几何（1）含解析的合订版（适合使用在线文档查看的同学）.pdf', 12, true, 152, null),
  ('0e10fe49-8f47-54ca-ab32-3d17e55e9619', '22222222-2222-2222-2222-222222222217', 'mcq', '一根长为2.5 米的梯子斜靠在垂直于地面的墙上，这时梯子的底端B 离墙根为0.7 米，如果梯子的底端向外(远离墙根方向)移动0.8 米至D 处，则梯子的顶端将沿墙向下移动( ).', '[{"key": "A", "text": "0.8米"}, {"key": "B", "text": "0.7米"}, {"key": "C", "text": "0.4 米"}, {"key": "D", "text": "0.3 米"}, {"key": "E", "text": "0.2 米"}]'::jsonb, '', '', '数学/第7章 平面几何（1）含解析的合订版（适合使用在线文档查看的同学）.pdf', 13, true, 153, null),
  ('d0648238-ae87-530a-a234-6bab50bb2378', '22222222-2222-2222-2222-222222222217', 'short', '等腰三角形{ 底边和腰不相等的等腰三角形 底边和腰相等的等腰三角形(等边三角形).', null, '', '', '数学/第7章 平面几何（1）含解析的合订版（适合使用在线文档查看的同学）.pdf', 14, true, 154, null),
  ('5231ee24-d13b-5d49-b96e-f67ecce5a469', '22222222-2222-2222-2222-222222222217', 'short', '等腰三角形顶角平分线平分底边并且垂直于底边.即等腰三角形的顶角 平分线、底边上的中线、底边上的高重合.（三线合一）', null, '', '', '数学/第7章 平面几何（1）含解析的合订版（适合使用在线文档查看的同学）.pdf', 14, true, 155, null),
  ('593a9ead-c776-5e6e-89c7-56e6e3ae1cf3', '22222222-2222-2222-2222-222222222217', 'short', '若等腰三角形的两腰长为𝑎，底边长为𝑏，则高ℎ= √𝑎2 −( 𝑏 2) 2 .', null, '', '', '数学/第7章 平面几何（1）含解析的合订版（适合使用在线文档查看的同学）.pdf', 14, true, 156, null),
  ('c19056de-faa0-596a-b2d1-224d4fe22a38', '22222222-2222-2222-2222-222222222217', 'short', '等边三角形', null, '', '', '数学/第7章 平面几何（1）含解析的合订版（适合使用在线文档查看的同学）.pdf', 14, true, 157, null),
  ('ec3bca65-6a09-53ab-8a37-78447af5625e', '22222222-2222-2222-2222-222222222217', 'short', '等边三角形的各个角都相等，并且每个角都等于60°.', null, '', '', '数学/第7章 平面几何（1）含解析的合订版（适合使用在线文档查看的同学）.pdf', 14, true, 158, null),
  ('a6150183-2678-5b67-95a9-9963079d42a2', '22222222-2222-2222-2222-222222222217', 'short', '面积公式：𝑆= √3 4 𝑎2.（☆） 你的坚持，终将美好！ 13 题型4：考查等腰三角形的应用', null, '', '', '数学/第7章 平面几何（1）含解析的合订版（适合使用在线文档查看的同学）.pdf', 14, true, 159, null),
  ('ac09af96-c455-57ec-b6c7-612350631c08', '22222222-2222-2222-2222-222222222217', 'mcq', '知知𝑥= 2是关于𝑥的方程𝑥2 −2𝑚𝑥+ 3𝑚= 0的一个根，并且等腰三角 形𝐴𝐵𝐶的腰和底边长恰好是这个方程的两个根，则△𝐴𝐵𝐶的周长为( ).', '[{"key": "A", "text": "12"}, {"key": "B", "text": "13"}, {"key": "C", "text": "14"}, {"key": "D", "text": "15"}, {"key": "E", "text": "16"}]'::jsonb, '', '', '数学/第7章 平面几何（1）含解析的合订版（适合使用在线文档查看的同学）.pdf', 15, true, 160, null),
  ('34a65b83-0a75-5e0c-af7e-ff229a8e6ab9', '22222222-2222-2222-2222-222222222217', 'short', '利用底和高求面积：𝑆= 1 2 𝑎ℎ，其中ℎ是长为𝑎的边上的高.', null, '', '', '数学/第7章 平面几何（1）含解析的合订版（适合使用在线文档查看的同学）.pdf', 16, true, 161, null),
  ('ad854a42-308e-531a-b7ac-b315986458c7', '22222222-2222-2222-2222-222222222217', 'short', '利用夹角求面积：𝑆= 1 2 𝑎𝑏sin𝐶= 1 2 𝑏𝑐sin𝐴= 1 2 𝑎𝑐sin𝐵，其中∠𝐶是长为𝑎和 𝑏的边所夹的角，其他同理. 𝜃 30°或150° 45°或135° 60°或120° 90° sin𝜃 1 2 √2 2 √3 2 1', null, '', '', '数学/第7章 平面几何（1）含解析的合订版（适合使用在线文档查看的同学）.pdf', 16, true, 162, null),
  ('7fb99122-0bc8-51d3-b338-2b2352063457', '22222222-2222-2222-2222-222222222217', 'short', '利用边长求面积：𝑆= √𝑝(𝑝−𝑎)(𝑝−𝑏)(𝑝−𝑐)，其中𝑝= 1 2 (𝑎+ 𝑏+ 𝑐). 也就是𝑝为三角形周长的一半.（海伦公式） 你的坚持，终将美好！ 15 题型5：考查三角形面积的求解', null, '', '', '数学/第7章 平面几何（1）含解析的合订版（适合使用在线文档查看的同学）.pdf', 16, true, 163, null),
  ('ced25838-1c5d-56d5-9db8-d5e21b502433', '22222222-2222-2222-2222-222222222217', 'mcq', '𝐴𝐵//𝐸𝐹，𝐶是𝐸𝐹上的一个动点，当点𝐶的位置变化时，△𝐴𝐵𝐶的面积将 ( ).', '[{"key": "A", "text": "不变"}, {"key": "B", "text": "变小"}, {"key": "C", "text": "变大"}, {"key": "D", "text": "变大再变小"}, {"key": "E", "text": "变小再变大"}]'::jsonb, '', '', '数学/第7章 平面几何（1）含解析的合订版（适合使用在线文档查看的同学）.pdf', 17, true, 164, null),
  ('fc6dc843-34a3-5684-8687-600ea5d3eb0a', '22222222-2222-2222-2222-222222222217', 'mcq', '若三角形有两边长为4 与6，三角形的面积为6√3，则这两边的夹角为 ( ).', '[{"key": "A", "text": "30°"}, {"key": "B", "text": "45°或135°"}, {"key": "C", "text": "60°或120°"}, {"key": "D", "text": "75°"}, {"key": "E", "text": "90°"}]'::jsonb, '', '', '数学/第7章 平面几何（1）含解析的合订版（适合使用在线文档查看的同学）.pdf', 17, true, 165, null),
  ('d4904aa1-ad19-595f-a0cb-b3c7131b1d24', '22222222-2222-2222-2222-222222222217', 'mcq', '若三角形的三边长分别为5,6,7，则三角形的面积为( ).', '[{"key": "A", "text": "4√6"}, {"key": "B", "text": "6√6"}, {"key": "C", "text": "8√6"}, {"key": "D", "text": "9√3"}, {"key": "E", "text": "12√2"}]'::jsonb, '', '', '数学/第7章 平面几何（1）含解析的合订版（适合使用在线文档查看的同学）.pdf', 18, true, 166, null),
  ('0f163cbd-9124-5e83-a789-fe1a10d9c3cc', '22222222-2222-2222-2222-222222222217', 'short', '概念：能够完全重合的两个三角形叫做全等三角形.故它们的边长、角、 面积都完全相等.', null, '', '', '数学/第7章 平面几何（1）含解析的合订版（适合使用在线文档查看的同学）.pdf', 19, true, 167, null),
  ('dd2fe4ca-5cde-58e6-a823-3a287c433988', '22222222-2222-2222-2222-222222222217', 'short', '三角形全等的判定（边side，角angle，斜边hypotenuse,直角边leg）', null, '', '', '数学/第7章 平面几何（1）含解析的合订版（适合使用在线文档查看的同学）.pdf', 19, true, 168, null),
  ('957fca49-4800-55f5-b4c5-b2dae7bbd82d', '22222222-2222-2222-2222-222222222217', 'short', 'SSS（边边边）：三边对应相等的三角形全等.', null, '', '', '数学/第7章 平面几何（1）含解析的合订版（适合使用在线文档查看的同学）.pdf', 19, true, 169, null),
  ('33e08cbc-0d5f-5112-9737-2ecdb485a165', '22222222-2222-2222-2222-222222222217', 'short', 'SAS（边角边）：两边及其夹角对应相等的三角形全等.', null, '', '', '数学/第7章 平面几何（1）含解析的合订版（适合使用在线文档查看的同学）.pdf', 19, true, 170, null),
  ('e3d18e00-6491-5a49-b919-6b44f556cf85', '22222222-2222-2222-2222-222222222217', 'short', 'ASA（角边角）：两角及其夹边对应相等的三角形全等.', null, '', '', '数学/第7章 平面几何（1）含解析的合订版（适合使用在线文档查看的同学）.pdf', 19, true, 171, null),
  ('e54e9bbf-6b68-567d-af56-e906554d0f8a', '22222222-2222-2222-2222-222222222217', 'short', 'AAS（角角边）：两角及其一角的对边对应相等的三角形全等.', null, '', '', '数学/第7章 平面几何（1）含解析的合订版（适合使用在线文档查看的同学）.pdf', 19, true, 172, null),
  ('effbaab3-ff5c-59b8-9499-3acb0892c345', '22222222-2222-2222-2222-222222222217', 'short', 'HL（斜边、直角边）：斜边及一条直角边相等的直角三角形全等', null, '', '', '数学/第7章 平面几何（1）含解析的合订版（适合使用在线文档查看的同学）.pdf', 19, true, 173, null),
  ('c8df543d-debe-54f0-bc68-6323f4dedda3', '22222222-2222-2222-2222-222222222217', 'short', '全等三角形的表示 全等用符号 “≌”表示，读作 “全等于”.如△𝐴𝐵𝐶≌△𝐷𝐸𝐹，读作 “三角 形𝐴𝐵𝐶 全等于三角形𝐷𝐸𝐹 ”.记两个全等三角形时，通常把表示对应顶点 的字母写在对应的位置上. 题型6：考查线段的求解', null, '', '', '数学/第7章 平面几何（1）含解析的合订版（适合使用在线文档查看的同学）.pdf', 19, true, 174, null),
  ('e223b761-6c2e-54be-8291-72e4cc3cd77d', '22222222-2222-2222-2222-222222222217', 'mcq', '在△𝐴𝐵𝐶中，𝐴𝐷⊥𝐵𝐶于𝐷，𝐶𝐸⊥𝐴𝐵于𝐸，𝐴𝐷与𝐶𝐸交于点𝐹，若𝐸𝐹= 𝐸𝐵= 3, 𝐴𝐸= 4，那么𝐶𝐹= ( ).', '[{"key": "A", "text": "1"}, {"key": "B", "text": "4"}]'::jsonb, '', '', '数学/第7章 平面几何（1）含解析的合订版（适合使用在线文档查看的同学）.pdf', 19, true, 175, null),
  ('e9ba4995-e438-5f1c-9594-a8cbc696a424', '22222222-2222-2222-2222-222222222217', 'short', '概念：对应角相等，对应边成比例的三角形叫做相似三角形，相似用符 号“ ”来表示，读作“相似于”.相似三角形对应边的比叫做相似比.本 质上形似的两个三角形是放大或缩小的关系.', null, '', '', '数学/第7章 平面几何（1）含解析的合订版（适合使用在线文档查看的同学）.pdf', 21, true, 176, null)
